import{_ as t,H as a,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"热点加餐｜从 OpenClaw 到 OpenCode：拆解爆款 Agent 的设计密码与工程范式","description":"","frontmatter":{},"headers":[{"level":2,"title":"OpenClaw、Claude Code 爆火给我们带来哪些启发？","slug":"openclaw、claude-code-爆火给我们带来哪些启发","link":"#openclaw、claude-code-爆火给我们带来哪些启发","children":[{"level":3,"title":"真实案例 · 大家都在用 OpenClaw 做什么？","slug":"真实案例-·-大家都在用-openclaw-做什么","link":"#真实案例-·-大家都在用-openclaw-做什么","children":[]},{"level":3,"title":"OpenClaw 架构拆解","slug":"openclaw-架构拆解","link":"#openclaw-架构拆解","children":[]},{"level":3,"title":"学习从哪里开始 ？先建立自己的认知地图","slug":"学习从哪里开始-先建立自己的认知地图","link":"#学习从哪里开始-先建立自己的认知地图","children":[]}]},{"level":2,"title":"Agent 落地的 3 个致命卡点","slug":"agent-落地的-3-个致命卡点","link":"#agent-落地的-3-个致命卡点","children":[]},{"level":2,"title":"从“会用 AI”到“会建 AI 系统”，一套通用方法论","slug":"从-会用-ai-到-会建-ai-系统-一套通用方法论","link":"#从-会用-ai-到-会建-ai-系统-一套通用方法论","children":[]}],"relativePath":"ClaudeCode工程化实战/热点加餐｜从OpenClaw到OpenCode：拆解爆款Agent的设计密码与工程范式.md","filePath":"ClaudeCode工程化实战/热点加餐｜从OpenClaw到OpenCode：拆解爆款Agent的设计密码与工程范式.md","lastUpdated":1779815462000}'),o={name:"ClaudeCode工程化实战/热点加餐｜从OpenClaw到OpenCode：拆解爆款Agent的设计密码与工程范式.md"};function l(s,e,r,i,g,d){return a(),n("div",null,[...e[0]||(e[0]=[p('<h1 id="热点加餐-从-openclaw-到-opencode-拆解爆款-agent-的设计密码与工程范式" tabindex="-1">热点加餐｜从 OpenClaw 到 OpenCode：拆解爆款 Agent 的设计密码与工程范式 <a class="header-anchor" href="#热点加餐-从-openclaw-到-opencode-拆解爆款-agent-的设计密码与工程范式" aria-label="Permalink to &quot;热点加餐｜从 OpenClaw 到 OpenCode：拆解爆款 Agent 的设计密码与工程范式&quot;">​</a></h1><p>晚上好，我是黄佳。很开心回到极客时间和大家进行阶段性的分享。这也是我在这段时间对 AI Agent 和 Agent 工程化进展的一阶段性梳理。</p><p>在 AI 时代，我们很多时候感觉自己生活在虚幻中，时间的流淌也和好像以前不一样了，有的人可能觉得过得更快了，所以我特别想强调一下这种真实的感觉，因为尤其是在这个时节，我们才特别能体会到人和人之间的那种连接的温暖。岁月的变迁，这是我所特别珍视的东西，珍惜的东西，也是我希望在 AI 时代所保持的。</p><p>我们现在已经把很多的工作代理给 AI Agent 来完成了。那么我们大家节省下来的时间，应该是我们每个人觉得更深刻的。</p><h2 id="openclaw、claude-code-爆火给我们带来哪些启发" tabindex="-1">OpenClaw、Claude Code 爆火给我们带来哪些启发？ <a class="header-anchor" href="#openclaw、claude-code-爆火给我们带来哪些启发" aria-label="Permalink to &quot;OpenClaw、Claude Code 爆火给我们带来哪些启发？&quot;">​</a></h2><p>AI Agent 发展到今天，它已经到了一个需要去粗取精、去伪存真的节点，因为在工具层面上可以说是百花齐放，几乎每几个礼拜都有新的东西。但真正能落地的产品是什么，应该其实还是数得过来的。</p><p>所以我们今天不谈趋势，不谈这个抽象的概念。我们就做这样一件事，我把两个爆款的 Agent 产品拆开来看。现在尽人皆知的Openclaw 还有 Claude Code 这两个真正爆款的 Agent 产品。我们将探讨以下问题。</p><ul><li><p>他们的底层逻辑，看看他们为什么能火出圈？</p></li><li><p>他们的工程 DNA 是什么？</p></li><li><p>我们能够在这两个爆款产品中学到点什么东西？</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/4780af7360b6167f75034577de60766d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/4780af7360b6167f75034577de60766d.png" alt="图片"></a></p><p>AI 时代，时间太宝贵了，所以一个小时之后，我希望你能够带着一点新的认知走，不要白来。我们先拆解产品，然后找到卡点，之后给出一些解法。我特别想强调的是： <strong>一个产品的设计密码和它的工程范式。</strong></p><p>我们不是教你用什么工具，无论是我专栏里 讲的Claude Code，还是接下来行动营准备用的 Open Code（或者阿里的灵码、字节的Trae）.这些工具的设计全部都有一个基本的方向——能够把 Agent 和大模型这个不确定的东西变成我们能够管理、管控的系统，所以我们的系统化思维特别重要，这是学习过程中要秉承的一个理念。</p><p>不是说现在 OpenClaw 火，就去学它。而是要想它现在火了，意味着半年之后会发生是什么情况。我们不是现在追风，而是先追上风，然后考虑风把我们带到什么地方去。言归正传，回到这两个爆款Agent上，看看能够抓到什么样的工程化本质？</p><p>先说 Claude Code，这是个闭源工具，但它的风头已经远远压过GPT，去年下半年比较流行的是一些比较好的单点模型（Gemini、Cursor、Nano Banana ）。而有了 Claude Code，它真正能给你干活，而且干活的质量说服了一切，因此成为热点，成为 Anthropic 增长最快的产品。它的底层很简单，就是你终于有了一个AI，你能够信任的 AI 给你当工程师。那么我们仔细拆解它背后这个系统怎么搭起来的？岂不是很有价值，很有意义？</p><p>第二个那就更不用说了。现在你如果说，哎，我还没有搭自己的 Openclaw 呢，都不好意思。我作为一个 AI 从业者，人家说你用了吗？ 用 Openclaw 做点啥事了吗？为什么它引起这么广泛的讨论？</p><p>首先，它是开源的。它是从这个 Claude Code 闭源平台再迁移出来，人家就是把所有的代码都给你开源，你自己也可以做二次开发。更关键的是。它让你的 AI Agent 能够入驻各种各样的聊天软件、接口。当你把 OpenClaw 在服务器跑起来，之后直接通过这个聊天软件连通后边的这个Agent，是不是这个想象力空间非常大？后面我们还会说说大家都在怎么玩 OpenClaw。</p><p>当下我收到了诸多来自社群的声音，在征得群友同意后，我将其中一些真知灼见分享给大家。其中不少观点我十分认同：例如有群友（冬瓜）提到，使用 Claude Code 后觉得自己起飞了。我也有同感，干活比过去更快，质量更高。他也提到，用了 Claude Code 和小龙虾之后，感觉所有岗位正出现同质化趋势 —— 无论前端从业者拥有五年还是十年经验，最终都依托同一类 AI 工具进行开发，产出质量趋于一致。这一观点引人深思。</p><p>由此我想提出一个问题：在 AI 工具高度强大且普及的时代，而且这些工具大家都用了，那你自身的特质何在？是否存在无论工具如何迭代升级，依然只属于你个人的不可替代价值？我无法给出标准答案，只能以此扪心自问，也希望在场每一位听众都认真思考：在熟练使用 AI 工具开展前端、后端等工作后，你与他人的核心差异究竟是什么？想清楚这个问题，未来的职业道路才会更加踏实。</p><p>我也十分认同另一位朋友（我的好友 Bruce）的观点：不少人热衷于参与各类 AI 相关交流大会，频繁讨论 OpenClaw 等工具，但真正依靠这些工具取得实际成果、创造价值的人并不多。我在新加坡也是一样，那这个千人大会、万人大会也多去了，就大家一起坐在一起，几百个人畅谈这个 Openclaw，说自己都怎么玩，然后问题是你有结果吗？对吧？你装一个软件，一个一句命令行的事， install 一下，谁不会呀？</p><p>因此我始终认为，AI 时代最后还是以人为本。我们更应思考：借助 AI 工具，我们究竟解决了哪些实际问题？为社会创造了怎样的价值？让社会变得更好了么？是否让我个人活得更清晰了？是否借助自动化工具腾出更多时间，可以陪伴家人、陪伴孩子了？这些才是我们真正需要思考的事儿。</p><p>稍微总结一下，工具带来的效率提升是真实的，使用过程中遇到的问题也是客观存在的。 <strong>起飞是真的，翻车也是真的，差距在哪里？实际上我们就是要有一双慧眼，穿透迷雾看本质。</strong></p><p>结合我自身经历，从零基础学习机器学习开始，我与大家同一时间使用 ChatGPT、Claude Code、OpenClaw 等工具，亲身经历了多次能力提升。2022 年 12 月初次使用 ChatGPT 时，我便感受到了显著进步；到 2023 年，我发现它能够思考了，你有了能够跟你切磋你的内心深处想法的、非常棒的对手。</p><p>ChatGPT 从 4 升级到 5 时，我真切感受到，它终于成为能与我深度同频的交流对象 —— 无论我思考到何种深度，它都能够承接并回应。这在 GPT‑4 阶段是难以实现的，彼时其理解能力与输出质量仍有明显不足。</p><p>而升级到新一代版本后，它真正具备了 <strong>深度思考能力</strong>，能为我带来很多启发。例如针对一个问题进行头脑风暴，让它从十个不同维度拆解分析，我的思路与它的输出相互碰撞，思维边界得到极大拓展，这是我第一次真正意义上的 “起飞”。</p><p>第二次起飞，是在 2025 年下半年接触到 Claude code。我在 <a href="https://time.geekbang.org/column/intro/101113501" target="_blank" rel="noreferrer">《Claude Code工程化实战》</a> 中以十分激动的心情向大家推荐这款工具，核心原因在于： <strong>AI 真正开始帮我 “干活” 了</strong>。每个人的时间都极其宝贵，此前我大量时间被代码编写、图书写作等事务占据，即便有清晰思路，也必须亲自落地。而现在，我只需给出核心思路，AI 便可快速生成初步的内容，再由我整理、优化完善。它从辅助思考变为实际执行，我的生产力实现了质的飞跃，这就是我的第二次能力跃升。</p><p>而第三次能否再次突破，关键在于能否借助 OpenClaw 的能力，实现更深层次的 AI 协作：让 AI 完成自动化运营，甚至自动化地代替你的一些思想。因为个人记忆长期驻留在OpenClaw里面，别人是否可以跟它沟通，让它当你的客服小助手。能不能弥补人力不足、运营跟不上的短板，让我与读者、用户的沟通更高效顺畅？比如以往有个人给我发个微信，我可能两三天才回复，未来有望通过AI实现即时响应。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/49835af3ae13635f3526845964a8a419.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/49835af3ae13635f3526845964a8a419.png" alt="图片"></a></p><p>每一次 “起飞”，本质不只是工具本身变强，更是 <strong>人与 AI 的协作深度不断升级</strong>：从最初的聊天机器人，到思考伙伴，再到如今可以并肩执行的工作搭档，人与 AI 的连接正变得愈发紧密与深入。从开始的一个 Chatbot （你的思考助手），到现在它是你干活的一个partner。</p><p>编程时，基于 SDD 规范驱动开发给它框架，让它帮你写代码。到最后，你提供它一个运营的流程，它帮你自动化地运营。若以这样的方式实践一遍，是不是有点意思？</p><p>由此我也产生了一些更深层次的洞察：这类 AI 工具抹平的是 <strong>执行层面的动作</strong>，导致相关岗位同质化了。正因如此，我们更应深入思考如何发掘并打造自身的独特特质。我们需要具备一双慧眼，清晰识别出未来终将被 AI 工具替代与抹平的能力 —— 这些能力不必再投入过多精力，而应将自身提升到“Level 3”——什么是 Agent 目前还抹不平的东西？需要加强这方面的技能。</p><p>若想在 AI 时代保持独特优势，就必须掌握更高维度的核心能力：并非单纯的编码能力，而是 <strong>系统性设计思维</strong>。这是 AI 短期内难以抹平的核心竞争力。具备这类设计思维，或是拥有很强的人际沟通能力，这一时间窗口预计会持续 5 到 8 年。</p><p>另一个观察就是我的好朋友萤火百宝箱，也就是极客时间的延飞老师。他提到，产品来来去去，什么东西会持久存在呢？他说Openclaw 不一定是未来，以后还可能有各种各样的 Claw。但其 <strong>背后的设计模式，一定是未来 。</strong> 也就是OpenClaw 带来的这种 AI 相互驱动，不同 Agent 彼此切磋，能在 Chatbot 上面去辅助我们做运营、做管理，这种模式一定代表未来。Claude Code 也不一定是未来，但是它里边隐藏的很多工程思想一定是未来，这些工程思想也是我想要提炼出来的东西。</p><p>我在近期书籍与课程中反复强调的重点：我不想再创作一类快速过时的工具类教程，例如 “21 天速成某框架”“手把手入门某工具”，这类内容往往三个月便失去价值。反之，若我们分析一个东西的设计模式，把这个模式沉淀下来，把系统拆解清楚，这个东西永远都会有价值。</p><p>这部分分享，核心是想和大家说明：我们既要看到表层现象，更要看透现象背后的本质。OpenClaw 之所以走红，并非因为技术有多么先进，而是它抓住了智能体真正具备执行与思考能力的节点，将智能体能力落地到交互场景中，并整合了多种消息渠道与能力系统（Skills），同时借鉴了 Claude Code 的思想。其作者最初的出发点，很可能就是看到 Claude 这么好，想打造一个开源版本，然后做得很成功。这一系列东西的出现，本质上是让一个能搭建智能体的人变成了能发布 AI 产品的人。理解到这一层便已足够。</p><p>而我想留给直播间每一位听众的问题（甚至是挑战）： <strong>当你手握这样的工具，你想要创造并发布一款怎样的 AI 产品？</strong></p><p>这类工具本身操作并不复杂，并无太多可讲授的技巧，核心在于启发大家思考。我十分认同黄仁勋的观点：如今智能体能力日益强大、大模型愈发智能，几乎没有什么是不能实现的。只要你拥有客户、明确需求，便可借助智能体满足客户、创造价值、实现收益。换言之，当前的核心问题并非技术能力不足，大模型已具备足够支撑。真正的难点在于，我们每个人都要思考：能为社会创造出怎样真正有价值的产品？一旦找准方向，再借助智能体与大模型技术落地实现，便不再是难题。</p><p>再次梳理一下思路的演进历程：2023 年，我们主要与 ChatGPT 进行对话交互；2024 年，各类 AI 工具逐步成熟，我们开始与 AI 协同工作；2025 年，Claude code 出现，真正在编程等具体工作中承担大量执行任务。至此，AI 仍主要作为 <strong>自用工具</strong> 提升个人效率。而到了 2026 年，我们需要思考的是：如何将智能体 <strong>产品化</strong>，打造出可供他人使用的产品与服务。</p><p>当然，并非所有人都必须去做产品，这条路本就不易。如果你本身是产品经理、具备成熟的产品思维，借助当前的智能体与自动化工具，创业成本已大幅降低，无需雇佣大量人力即可启动；但若你并不具备强烈的产品思维，也不必强求。</p><p>但是如果说你没有那么强的这个产品思维。此时此刻，你可以考虑的是“实际任何人都是你的客户”，比如说你在公司里边，你的同事、你的团队，你的这个上级下级，你都可以用这个 OpenClaw 给他们搭建一些系统，然后去把你的工作环境中各种各样的事情给它流程化，对吧？或者说你自己就是你自己的客户，你建立起更好的个人的知识库系统。这个也叫产品化思维，说是给别人用。</p><h3 id="真实案例-·-大家都在用-openclaw-做什么" tabindex="-1"><strong>真实案例 · 大家都在用 OpenClaw 做什么？</strong> <a class="header-anchor" href="#真实案例-·-大家都在用-openclaw-做什么" aria-label="Permalink to &quot;**真实案例 · 大家都在用 OpenClaw 做什么？**&quot;">​</a></h3><p>我让智能体自动抓取相关信息，而非手动收集，这些信息我认为具备真实性，也未再逐一验证。这一页 PPT 的内容，我同样没有自行构思，而是直接让智能体搜集当前大家使用 OpenClaw 的主流场景，生成后直接使用，从中也能为我们带来不少启发。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/8d1e294c72537eea32e4cc0ed32be138.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/8d1e294c72537eea32e4cc0ed32be138.png" alt="图片"></a></p><p>我始终认为，这类工具在未来几年里，真正能够推动社会向好发展。我自身也参与义工与心理辅导工作，接触过不少一线中小学教师。曾有位中学老师和我说，看着老师应该做很多教学工作。但现实里大量时间却在做流程性的东西，文档处理、学费跟进、假期活动安排等等，在国外这些叫paperwork（纸面工作），校领导不请帮手，都是老师在做。</p><p>我的想法是，教育核心价值本应是培养孩子，需要老师用更多时间按思考如何更好地教育班级里的学生。但现实中，大量时间却被文档整理、费用统计、活动安排等行政事务占据，这类繁琐的文书工作，严重挤压了本该用于教育教学的时间。</p><p>在我看来，这类事务性、流程化的工作，未来完全可以借助 OpenClaw 等智能体工具来承担。虽然这一愿景的全面落地仍需时间，但方向极具社会价值：让 AI 替代教师完成琐碎事务、流程管理与基础沟通，让教师回归育人本质，将精力聚焦在最核心、最有价值的工作上。</p><p>我以教师为例，也想请直播间的每一位听众思考：你希望 OpenClaw 这类工具帮你解决哪些事务？你又想把节省下来的思考精力，投入到哪些更有价值的事情中？这正是我们在 AI 时代需要直面的核心问题。</p><h3 id="openclaw-架构拆解" tabindex="-1"><strong>OpenClaw 架构拆解</strong> <a class="header-anchor" href="#openclaw-架构拆解" aria-label="Permalink to &quot;**OpenClaw 架构拆解**&quot;">​</a></h3><p>接下来拆解 OpenClaw 的底层架构。我认为它最独特的优势，并非单纯的代码能力，而是 <strong>消息网关（Gateway）</strong>—— 这也是它与 Claude Code、Cursor 等工具最本质的区别。它打通了微信、Telegram、飞书、钉钉等多平台消息入口，实现统一接入与管理。这正是设计模式中的 <strong>中介者模式</strong>：将所有入口归一化，大幅降低使用与管理成本。</p><p>我们继续看下面这张图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/2f2fc85861ebf77ee9yy17804dd9d0e1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/2f2fc85861ebf77ee9yy17804dd9d0e1.png" alt="图片"></a></p><p><strong>人设、技能、记忆</strong>，有没有感觉底层架构与 Claude Code 完全一样。所有智能体系统的设计逻辑都遵循这样的范式，不同智能体仅在具体技能上存在差异。</p><p>而 OpenClaw 真正实现破圈的核心密码，正是它额外搭载的 <strong>消息网关</strong>，这也引爆这场流行趋势的真正密码所在，是这个软件的灵魂。通过架构拆解，这一核心优势一目了然。</p><p>顺便一提，在准备下面的行动营期间，我计划将 OpenCode 替代 Claude Code 使用，结果发现二者的配置逻辑高度相通。我正在通过 Open Code 搭建行动营里的知识库，配置插件、实现知识检索、挂载钩子函数，并通过 Python 文件做知识库的质量检查。这一套配置过程走下来，我发现其中的逻辑，和 Claude code 完全一致。</p><p>这让我意识到： <strong>掌握一套核心逻辑，很容易就能适配多种框架</strong>。因为其底层模式高度统一，一旦将这套流程拆解清晰，无论未来智能体技术如何迭代演进，都能做到万变不离其宗。</p><p>ClaudeCode 的核心正是 <strong>智能体闭环（agent loop）</strong>，这套逻辑早在我撰写《动手做 AI agent》一书时便已确立： <strong>思考 — 行动 — 观察 — 复盘 — 再思考 — 再执行</strong>，循环往复直至达成目标，这也是所有智能体运行的底层逻辑。</p><p>依托智能体自身记忆储备、专属技能、下属的子智能体（SubAgents），再联动 MCP 外部工具及各类系统工具，将所有模块打通、拼接串联，这便是 Claude Code背后深藏的工程思想。我们真正要学的，从来不是单一工具的操作技巧，而是这套底层工程思想。这套（更加通用的 ）DNA，也就是我希望和大家一同吃透。此刻大家不妨截图留存，这也是我们学习智能体设计和把握爆款 Agent 产品密码的关键。</p><p>如下图所示，我已经将其提炼为清晰的七维 DNA 框架，内容直白易懂。所有核心模块拆解完毕后，整体逻辑一目了然。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/cf7358ef351f16ae30b3cyy204390cbe.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/cf7358ef351f16ae30b3cyy204390cbe.png" alt="图片"></a></p><ul><li>在OpenClaw中对应记忆模块，在Claude Code中则通过claude.md实现角色定位与灵魂塑造；</li><li>子智能体对应分工，绑定能力等同于核心技能；</li><li>事件机制与钩子函数，负责把控功能激活、流程校验与结果复盘；</li><li>此外还有外部工具连接、定时任务功能、自动化CI/CD部署以及长期记忆存储。</li></ul><p>在未做深度拆解之前，你可能觉得一团乱麻；而完成底层拆解后，便能一眼看透本质。我们要做的，正是穿透各类爆款产品的表层现象，抓住其背后共通的核心价值与底层逻辑。</p><p>事实上，这类主流智能体工具的内核本就高度一致，核心能力底层相通，区别仅在于场景侧重： <strong>Claude Code的核心优势是落地执行，能够直接协助完成具体工作；OpenClaw的核心亮点则是依托消息网关，打通各类聊天平台与消息入口，实现多渠道统一接入。</strong></p><p>二者的本质逻辑从未改变，核心循环都是智能体的Loop，我在2024年撰写的《动手做AI Agent》一书中所阐述的，一切都没有变味。</p><h3 id="学习从哪里开始-先建立自己的认知地图" tabindex="-1">学习从哪里开始 ？先建立自己的认知地图 <a class="header-anchor" href="#学习从哪里开始-先建立自己的认知地图" aria-label="Permalink to &quot;学习从哪里开始 ？先建立自己的认知地图&quot;">​</a></h3><p>最后我还想和大家分享一个感想：不少读者常向我反馈，AI领域知识繁杂、工具迭代过快，难免觉得眼花缭乱，迷茫于 AI 时代，学习从哪里开始 。</p><p>其实这个问题的答案很简单，我也反复强调过核心思路——搭建属于自己的 <strong>认知地图</strong>，也就是清晰的思维框架，这一点看似题外话，但我认为很重要。</p><p>很多人觉得 AI 相关内容太多，不知道学啥。即便学了什么，也无法纳入自身知识体系。根源就在于大脑中没有搭建起这张认知地图。反之，若你的认知地图足够清晰和准确，即便出现新东西，也只需将其对应放到地图里的合适位置即可。就像一张世界地图，有中国、美国，突然有个北极的新国家出来了，你把它放北极这个位置就行了，你完全不需要重构你的世界（那个是颠覆性的）。我们把已有的思维地图打磨得越清晰、越准确，后续学习才能越高效。</p><p>至此，第一阶段的分享也接近尾声，最后我想留下一个直击核心的灵魂拷问：有些人每天消耗数亿Token，日均生成几十万行代码、几百篇内容，可最终的实际成果是什么？千万不要把单纯的过程消耗，当成值得骄傲的成绩。</p><p>我们耗费大量Token与电力资源，抛开金钱成本不谈，更应该思考能为世界带来怎样的正向改变？这也是我此前特意举例中小学教师群体的原因：他们本该把核心精力放在教书育人、培育下一代上，却被大量文档事务挤占时间。如果智能体工具能替他们完成这类琐碎工作，他们就能回归本职，为社会培养更优秀的人才，这才是AI工具真正的价值所在。</p><p>蒙曼老师也曾说过，AI 给出的答案，是 <strong>基于过往数据的过去式答案，唯有人类，才能创造出面向未来的全新答案</strong>。面对愈发强大的 AI，我们更应携手并肩，依托 AI 工具突破自我局限，共同创造更美好的未来。</p><h2 id="agent-落地的-3-个致命卡点" tabindex="-1">Agent 落地的 3 个致命卡点 <a class="header-anchor" href="#agent-落地的-3-个致命卡点" aria-label="Permalink to &quot;Agent 落地的 3 个致命卡点&quot;">​</a></h2><p>在智能体实际落地过程中，目前还存在三大核心卡点。</p><p>第一大卡点，AI 的行为不可预测 点，那实际上这个问题的解法就是说我们现在要对 AI 的这个工程进行约束，这个就是我觉得是 Claude Code 工程化实战解决的最大的问题，就是我们如何通过理解工程的结构，通过这些东西去给Claude声明边界，去约束它.</p><p>未来的程序开发模式，也将转向 <strong>规范式开发</strong>。核心逻辑在于撰写清晰完备的 SPEC，只要规范文档足够精准、足够细致，AI就能严格依照规范执行任务；后续还有监管问题，需要 Hooks 做检查，这都是我们要贯通的能力。</p><p>第二大卡点，是 <strong>AI能力无法复用</strong>。日常应用中往往存在这类痛点：今天为 AI 设定的指令与逻辑，隔天需要重新配置；换一个应用场景，就要重新搭建逻辑；团队内部更是缺乏统一标准，不同成员使用 AI 的方法、配置的逻辑各不相同，新员工接手又要重新摸索，导致大量重复劳动，效率极低。</p><p>针对这一问题，我们需要建立一套标准化、可复用的技能体系与方法论，将AI的核心技能、执行逻辑沉淀为通用模块，实现一次配置、多场景复用、跨团队共享，彻底打破能力复用壁垒。当然，这套体系并非简单的复制粘贴，需要结合具体项目场景灵活适配，这也是我们需要掌握的核心贯通能力。</p><p>第三大卡点，是 <strong>复杂任务处理易陷入混乱</strong>。AI应对单一、简单任务时表现稳定，可一旦面对多环节、高复杂度的综合任务，就容易出现逻辑混乱、上下文混淆、执行偏差的问题。</p><p>对应的解决方案，是搭建 <strong>子智能体（Subagent）</strong> 体系，通过专业化分工实现任务拆解与上下文隔离，让专属智能体负责对应细分任务。需要明确的是，子智能体并非比主智能体更“聪明”，核心作用是划分清晰的任务边界与职责区间，让每个智能体专注于单一模块工作，避免多任务混杂导致的逻辑紊乱，保障复杂任务有序推进、高效落地。</p><p>这种借助子智能体拆解复杂任务的方式，本质是复杂系统的简化方法论，与麦肯锡金字塔思维有点像。咨询公司面对庞杂的大型任务时，核心思路便是 <strong>逐级拆分、化整为零，</strong> 将宏大目标拆解为层层递进、清晰可执行的细分步骤，子智能体承担的正是这一角色，核心价值在于精细化拆解。</p><p>除此之外，还有 Claude 提出的 Teams 协作范式，主打多智能体协同，也就是不同智能体之间可自主沟通、联动协作，同时与主智能体形成高效配合。实际项目落地中，没有绝对最优的范式，只需结合项目场景、任务特性选择适配模式即可，灵活选用不同范式解决问题，正是前文提到的规范驱动开发核心DNA。</p><h2 id="从-会用-ai-到-会建-ai-系统-一套通用方法论" tabindex="-1">从“会用 AI”到“会建 AI 系统”，一套通用方法论 <a class="header-anchor" href="#从-会用-ai-到-会建-ai-系统-一套通用方法论" aria-label="Permalink to &quot;从“会用 AI”到“会建 AI 系统”，一套通用方法论&quot;">​</a></h2><p>所谓在工程落地层面的关键密码，就是将智能体体系按协作层、能力层、规范层逐级拆解透彻（这也是我们《多Agent 设计与工程化》行动营的交付设计，即便只是短期的四周训练，也能完整理清这套逻辑并完成实操落地）。</p><p>归根结底，Claude Code背后的核心，是一套成体系的 <strong>工程化思想</strong> 与能力框架，这也是我反复强调的核心要点。这套思想体系，将在未来陪伴我们很长一段时间，必须将其彻底内化，它是一个宏观认知框架。掌握这套框架，不仅能熟练运用智能体、指挥智能体，更能快速理解各类全新的智能体架构，而未来3-5年的AI开发范式，也将围绕这套逻辑展开。</p><p>更关键的是，这套工程化能力并非与Claude Code深度绑定，不属于单一工具的专属能力。当我们吃透这套逻辑，即便脱离Claude Code工具本身，也能灵活迁移复用。比方说，你的公司跟你说，小王同学，给咱们某某公司自己开发一套这个代码审查体系，做自己的 Agent 系统编排。</p><p>来吧。怎么办？没有 Claude Code，你就需要去复制这 6 大工程化能力，你复制好了，你不就把这个东西开发出来了吗？所以这些思想体系，工程的六个核心概念（Memory、 Sub-agent、Skills，Hooks、MCP、Headles）是我们永远要记住的。像 OpenCode 也是完全映射了这全部的 6 个概念。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/92835083aae4478c05bdbfab15e4499f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/92835083aae4478c05bdbfab15e4499f.png" alt="图片"></a></p><p>这些爆款的工具，Claude Code 也好， OpenClaw 也好，它们的 终极价值就是给了你一套 Agent 系统设计的密码你可以在这个密码的基础上以用好它。懂了这一套密码，既可以把 Claude Code 用得更好，也可以定制开发你自己的 专属 Agent 系统，你自己去做工作流编排。万变不离其宗，这些组件你自己设计的系统里都得有，如果没有的话，对不起，那可能你还没有深刻地理解 Claude Code 的内核。</p><p>对于我们普通使用者，随着 Skills 越来越多，越来越清晰，核心不在于盲目堆砌技能数量，而在于系统化梳理、精细化归类，形成自己的 <strong>专属AI系统</strong>。</p><p>在此我也可以分享一下 ：我自身就搭建了一套完整的专属写作技能体系，这是我的专属能力，我的 Agent 有强大的写作 Skill，跟你的绝对不一样。它适合我，不一定适合你，这就是专属。</p><p>并非所有人都需要具备高强度的文档产出能力，需求不同，专属AI系统的定位与功能也截然不同。举例而言，若为一线教师打造专属AI系统，核心就要侧重教育教学辅助能力、行政文书（前面说的paperwork）自动化处理能力，精准匹配教师群体的核心工作需求，这便是专属 AI 系统的真正内涵。</p><p>站在2026年春末夏初这个关键节点，AI 应用正式迈入工程化深水区，我们也迎来了核心分水岭： <strong>从“会使用AI工具”升级为“会搭建 AI 系统”</strong>。仅仅满足于基础使用AI早已跟不上行业发展节奏，真正的核心竞争力，在于具备独立搭建适配自身或场景需求的 AI 系统的能力。而搭建逻辑与前文一脉相承，无论是使用Openclaw、Claude Code还是各类同类工具，都必须先吃透前面说的那一套理念。</p><p>回到前面群友说的 那个观点，岗位同质化的问题。各类岗位能力趋于同质化，所有人借助AI产出的成果水平相近，而周老师（另一位群友）则提出了不同的看法：即便拥有同样的工具与方法论，最终成果也未必同质化。这就好比给所有人同样的炒锅与菜谱，也并非每个人都能做出味道完全一致的菜肴，核心差异在于使用者本身。</p><p>好，我已经把规范驱动开发的核心逻辑、七维 DNA 密码架构这类底层方法论全盘分享，没有任何保留，后续可以通过系统化学习与实操演练，把这套逻辑走通练熟。</p><p>剩下的就是你自己的“厨艺”，你的判断力，没有人能取代你自己对于 AI 的感悟和你每天做的事儿。这些是无法通过教学直接传递的核心能力。每个人的生活阅历、工作履历、行业积累各不相同，对 AI 的理解与运用方式也千差万别，这份独属于个人的“软实力”，正是AI时代无法被替代的核心特质，也是我们在 AI 浪潮中站稳脚跟的关键。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/yyfacc4f51774632287f35197900c231.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/yyfacc4f51774632287f35197900c231.png" alt="图片"></a></p><p><strong>写代码的时代结束了。写规范的时代开始了。</strong> 最后我想传递的第三点核心启发：单纯学习工具极易过时，跟风追逐各类新兴工具只会疲于应对；而深耕底层思想，既能保持学习的连贯性与愉悦感，更能长期适配行业迭代，始终走在趋势前沿。核心从来不是跟风玩透某一款工具，而是借助工具解决实际问题、实现自我认知升级，这才是AI应用的核心价值。</p><p>最后想和大家厘清一个核心认知： <strong>产品形态只是表层浪花，底层范式才是恒久的洋流；工具只是执行载体，系统思想才是核心竞争力。：</strong> 会使用各类AI工具并非稀缺能力，人人都可快速上手，能依托工具解决实际问题、实现认知突破，才是真正的硬本事。</p><p><a href="https://u.geekbang.org/subject/intro/1011199" target="_blank" rel="noreferrer"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/1f662fcc23c665abbc1c8763cdc57390.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/954122/1f662fcc23c665abbc1c8763cdc57390.jpeg" alt=""></a></a></p><p>行动营详情链接 ： <a href="https://u.geekbang.org/subject/intro/1011199" target="_blank" rel="noreferrer">https://u.geekbang.org/subject/intro/1011199</a></p>',97)])])}const c=t(o,[["render",l]]);export{A as __pageData,c as default};
